import{_ as a,o as t,c as s,ak as i}from"./chunks/framework.WEfAUR5x.js";const g=JSON.parse('{"title":"GCP Parameter Manager","description":"","frontmatter":{},"headers":[],"relativePath":"guide/inheritance/gcp-parameter.md","filePath":"guide/inheritance/gcp-parameter.md","lastUpdated":1779040688000}'),r={name:"guide/inheritance/gcp-parameter.md"};function n(o,e,l,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="gcp-parameter-manager" tabindex="-1">GCP Parameter Manager <a class="header-anchor" href="#gcp-parameter-manager" aria-label="Permalink to “GCP Parameter Manager”">​</a></h1><p>Read parameters from <strong>Google Cloud Parameter Manager</strong>.</p><p>Unlike Secret Manager, Parameter Manager is <strong>location-scoped</strong>: every parameter lives under <code>projects/{project}/locations/{location}/parameters/{name}</code>. Pika defaults to the <code>global</code> location and lets you override it per resource.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><p>Under <strong>Settings → External Resources → Add Resource → GCP Parameter</strong>:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Type               : GCP Parameter</span></span>
<span class="line"><span>ServiceAccountJSON : { &quot;type&quot;: &quot;service_account&quot;, ... }   (full JSON key, pasted)</span></span>
<span class="line"><span>Location           : global                                (or e.g. us-central1)</span></span></code></pre></div><ul><li><strong>ServiceAccountJSON</strong> — the full JSON key of a service account with the <code>roles/parametermanager.parameterAccessor</code> role on the parameters Pika should read. Pika derives the GCP project ID from this JSON.</li><li><strong>Location</strong> — defaults to <code>global</code> when empty. Use a regional location only if your parameters are regional. Pika automatically targets the matching regional endpoint (<code>parametermanager.&lt;region&gt;.rep.googleapis.com</code>) so cross-region requests don&#39;t fall back to the global endpoint, which rejects them with a misleading 403.</li></ul><div class="warning custom-block"><p class="custom-block-title custom-block-title-default">WARNING</p><p>The service-account JSON is stored in the database. Set the <a href="./../encryption">encryption key</a> so it&#39;s encrypted at rest.</p></div><h2 id="inheritance-entry" tabindex="-1">Inheritance entry <a class="header-anchor" href="#inheritance-entry" aria-label="Permalink to “Inheritance entry”">​</a></h2><p><code>path</code> is the parameter name. Pika hits the <code>:render</code> endpoint, so JSON/YAML parameters that reference Secret Manager versions are resolved server-side in a single round trip.</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;resource&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myapp-params&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myapp-config&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;inject&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;database&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>By default Pika reads the <code>latest</code> version. To pin a specific version, use either form:</p><div class="language-json"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myapp-config/versions/v3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;myapp-config/v3&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><h3 id="payload-formats" tabindex="-1">Payload formats <a class="header-anchor" href="#payload-formats" aria-label="Permalink to “Payload formats”">​</a></h3><p>Parameter Manager parameters have a format (UNFORMATTED, JSON, YAML):</p><ul><li><strong>JSON / YAML</strong> — Pika parses the rendered payload into a map and merges its fields the same way Secret Manager JSON secrets do.</li><li><strong>UNFORMATTED</strong> — Pika returns <code>{&quot;value&quot;: &quot;&lt;string&gt;&quot;}</code> so callers can still <code>inject</code> it into a single config field.</li></ul><p>See <a href="./">Inheritance</a> for the full meaning of <code>paths</code> / <code>inject</code>.</p><h2 id="differences-from-gcp-secret-manager" tabindex="-1">Differences from GCP Secret Manager <a class="header-anchor" href="#differences-from-gcp-secret-manager" aria-label="Permalink to “Differences from GCP Secret Manager”">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Secret Manager</th><th>Parameter Manager</th></tr></thead><tbody><tr><td>Resource shape</td><td><code>projects/p/secrets/X</code></td><td><code>projects/p/locations/L/parameters/X</code></td></tr><tr><td>Location</td><td>n/a (global)</td><td>required, default <code>global</code></td></tr><tr><td>IAM role</td><td><code>roles/secretmanager.secretAccessor</code></td><td><code>roles/parametermanager.parameterAccessor</code></td></tr><tr><td>Secret references</td><td>resolved by caller</td><td>resolved by <code>:render</code> server-side</td></tr><tr><td>Version history in browser</td><td>No</td><td>Yes — newest-first strip, disabled versions painted amber</td></tr><tr><td>Writable from Pika</td><td>No</td><td>No</td></tr></tbody></table><p>Both backends share the same JWT/OAuth2 token exchange (scope <code>cloud-platform</code>), so the same service account can drive both — just grant the matching IAM roles.</p>`,20)])])}const k=a(r,[["render",n]]);export{g as __pageData,k as default};
